using System;using System.Linq;using System.Text.Json;using System.Collections.Generic;using System.Windows.Forms;using Observatory.UI;class Program{static void Main(){System.Globalization.CultureInfo.CurrentCulture=System.Globalization.CultureInfo.GetCultureInfo("en-US");string[]inputs={"","A","a","Body 1","Body 2","Body 10","Body 01","Body 001z","Body1x","Body01a","1.2","1.10","-1.2","-1.10","00","0","0x","00y","12,345","2,000","Z","Ω","π","é","😀","9","١","1","١٠","10"};var cases=new List<object>();var sorter=new DefaultSorter{Order=1};foreach(var left in inputs)foreach(var right in inputs)cases.Add(new{left,right,order=Math.Sign(sorter.Compare(new ListViewItem(left),new ListViewItem(right)))});Console.Write(JsonSerializer.Serialize(cases));}}